DOMAIN_CODE={
 'foundations':('@prefix ex: <https://example.org/learning/> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\nex:TopicRDF a skos:Concept ; skos:prefLabel "RDF"@en .\nex:Course101 ex:teaches ex:TopicRDF .','Every IRI refers to a reusable thing, and the English label is data about a concept.'),
 'modeling':('@prefix ex: <https://example.org/research/> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\nex:ResearchDataset rdfs:subClassOf ex:ResearchAsset .\nex:StudyOutput a ex:ResearchDataset .','Subclasses describe inferable categories; they are not validation rules by themselves.'),
 'building':('PREFIX ex: <https://example.org/catalog/>\nSELECT ?dataset ?steward WHERE {\n  ?dataset ex:steward ?steward .\n} ORDER BY ?dataset LIMIT 10','This is a SPARQL SELECT query over a graph that contains the ex:steward predicate.'),
 'advanced':('@prefix ex: <https://example.org/platform/> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\nex:Publication7 prov:wasDerivedFrom ex:SourceSnapshot12 .','Provenance connects a published artifact to evidence of its input data.'),
 'metadata':('@prefix ex: <https://example.org/catalog/> .\n@prefix dcat: <http://www.w3.org/ns/dcat#> .\n@prefix dct: <http://purl.org/dc/terms/> .\nex:Customer360 a dcat:Dataset ; dct:title "Customer 360"@en ; dct:publisher ex:DataOffice .','The catalog entry records what the dataset is and who publishes it.'),
 'master':('@prefix ex: <https://example.org/mdm/> .\nex:CRM_C17 ex:mapsToMaster ex:Master_102 .\nex:ERP_E104 ex:mapsToMaster ex:Master_102 .','Both source identities remain visible even after a governed master is assigned.'),
 'reference':('@prefix ex: <https://example.org/rdm/> .\n@prefix skos: <http://www.w3.org/2004/02/skos/core#> .\nex:Active a skos:Concept ; skos:prefLabel "Active"@en ; skos:altLabel "Enabled"@en .','A stable concept can be reached through multiple lexical labels.'),
 'semantic':('@prefix ex: <https://example.org/ontology/> .\n@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .\nex:DataProduct rdfs:subClassOf ex:EnterpriseAsset .','Subclasses express a formal hierarchy for downstream inference.'),
 'integration':('@prefix ex: <https://example.org/integration/> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\nex:MasterSnapshot2 prov:wasDerivedFrom ex:CRMSnapshot10 .','An update should preserve lineage to the exact source snapshot.'),
 'engineering':('@prefix ex: <https://example.org/pipeline/> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\nex:SilverData prov:wasDerivedFrom ex:BronzeData .','Pipeline lineage should remain queryable across ingestion stages.'),
 'governance':('@prefix ex: <https://example.org/governance/> .\n@prefix dct: <http://purl.org/dc/terms/> .\nex:CustomerDictionary dct:publisher ex:DataGovernanceOffice .','Published semantic assets should have a named accountable publisher.'),
 'products':('@prefix ex: <https://example.org/products/> .\n@prefix dcat: <http://www.w3.org/ns/dcat#> .\nex:SalesMetrics a dcat:Dataset ; ex:ownedBy ex:FinanceDomain .','Make the product identity and ownership explicit before advertising reuse.'),
 'industry':('@prefix ex: <https://example.org/synthetic/> .\nex:Study52 ex:producedDataset ex:Dataset52 .\nex:Dataset52 ex:ownedBy ex:ResearchOffice .','Fictional examples allow practicing traceability without sharing sensitive source data.'),
 'ai':('@prefix ex: <https://example.org/graphrag/> .\n@prefix prov: <http://www.w3.org/ns/prov#> .\nex:Answer42 prov:wasDerivedFrom ex:SourceSnippet42 .','A generated answer needs inspectable evidence links, not just narrative fluency.'),
}

# Individually authored technical notes; matched by the full lesson title or a specific technical phrase.
# We keep them distinct from broad path patterns to avoid teaching e.g. SKOS as OWL classification.
SPECIFIC=[
 ('data versus information versus knowledge','Raw observations become information when given relevant context; knowledge adds interpretable relationships and justified conclusions. None of these layers creates truth merely through a naming convention.', 'A temperature of 37.1 is a number; an observation with unit, time, device and patient context becomes interpretable; a clinically justified conclusion needs more evidence and explicit rules.'),
 ('what is a concept','A concept is a unit of thought within a knowledge-organization system. A concept IRI is distinct from both a label string and from an individual real-world object.', '“Active” may be a SKOS status concept used to categorize many customer records; the concept itself is not one of those customers.'),
 ('what is an entity','An entity is a thing treated as having identity in the modeling domain. Different source records may represent the same entity without their record identifiers becoming interchangeable.', 'CRM customer C44 and ERP customer E900 may refer to one legal organization; keep both source record keys.'),
 ('what is a relationship','A relationship connects two identifiable referents. Its predicate should document direction, meaning, expected subject/object types and whether the link is asserted, derived or proposed.', 'ex:Dataset ex:ownedBy ex:Team means the dataset is owned by that team; reversing subject/object changes the claim.'),
 ('what is an attribute','An attribute records a characteristic of an entity, often as a typed literal or a value taken from a governed code scheme. Relationship versus attribute is a modeling choice driven by reuse and identity.', 'A dataset title is commonly a string; its steward is better modeled as a link to a steward entity.'),
 ('directed versus undirected relationships','RDF predicates are directed from subject to object. If a business relation is symmetric, that property can be modeled explicitly, but the basic RDF triple remains directional.', 'For example, ex:knows may be declared symmetric in OWL; ex:owns is not normally symmetric.'),
 ('blank nodes','A blank node denotes an unnamed resource with local identity in an RDF graph. Its generated identifier is not a durable global identity for interchange across systems.', 'Use a blank node for a self-contained address structure only if external systems do not need to reference the address persistently.'),
 ('literal datatypes','An RDF literal consists of a lexical value and datatype (or a language tag). Datatypes affect comparison and query behavior; text representing a date is not necessarily an xsd:date.', '"2026-10-22"^^xsd:date identifies a date value, while "2026-10-22" is ordinarily a string.'),
 ('language-tagged strings','Language-tagged literals allow multilingual labels without minting separate entities for translations. Tags belong to the literal value and are meaningful in search and display policies.', 'skos:prefLabel "Active"@en and "Actif"@fr can describe the same concept.'),
 ('namespaces explained','Namespace prefixes are compact abbreviations of IRIs in syntaxes such as Turtle. They do not create distinct identifier spaces inside an RDF graph beyond the expanded full IRI.', 'Changing ex: to org: does not change the meaning if both expand to the same namespace IRI.'),
 ('semantic interoperability','Semantic interoperability means independent consumers interpret shared data consistently, not merely that they can parse the same file format.', 'Two systems may exchange JSON successfully yet disagree whether customerStatus=1 means active or pending; an approved concept mapping makes the meaning explicit.'),
 ('open versus closed world','Open-world semantics permit facts to be unknown when not asserted. Closed-world validation tests whether available data satisfies prescribed requirements.', 'OWL cannot generally conclude that a record lacks a manager merely because no manager triple was loaded; SHACL can report a missing required manager.'),
 ('competency questions','A competency question is a requirement expressed as a question the ontology and graph should support. It provides measurable scope for deciding entities, relations and queries.', '“Which products use components from suppliers in a flagged region?” suggests classes, relations and a repeatable SPARQL acceptance test.'),
 ('exact match versus close match','skos:exactMatch communicates a high-degree cross-scheme concept match suitable for many retrieval uses; skos:closeMatch acknowledges substantial similarity without the same substitutability commitment.', 'Do not convert two closeMatch links into owl:sameAs: identity reasoning could collapse distinct concepts.'),
 ('broad match versus narrow match','SKOS broad/narrow mapping relates concepts in different schemes at different specificity levels. The direction matters and is not interchangeable with a superclass inference in OWL.', 'Map a detailed local category “Cardiac imaging” to broader external “Diagnostic imaging”, preserving cross-scheme provenance.'),
 ('skos collections','A SKOS Collection is a curated grouping of concepts that may support navigation or display. It is not by itself a ConceptScheme and does not imply a broader/narrower relationship.', 'Place popular subject tags into a display collection without changing their real conceptual hierarchy.'),
 ('skos top concepts','skos:topConceptOf or skos:hasTopConcept identifies root-level concepts within a specified ConceptScheme. A concept can be reused across schemes with different navigational structure.', 'Concept schemes are governance boundaries; top concepts aid browsing rather than implying logical class inheritance.'),
 ('preferred and alternative labels','A preferred label is the accepted display term per language; alternative labels represent synonyms or search variants, not new concept identities.', 'Store “Heart attack” as an alternate label of a governed concept only when the lexical meaning is really equivalent for the vocabulary’s scope.'),
 ('hidden labels for search','skos:hiddenLabel is used for lexical forms useful to search but not appropriate for normal display, such as common misspellings.', 'Do not place secret or personal strings into a hidden label: hidden means not preferred for display, not confidential.'),
 ('definition and scope notes','Definitions identify the intended meaning; scope notes communicate usage boundaries and inclusion/exclusion guidance. They should not be replaced by one-word labels.', 'A “Customer” definition may specify whether leads, former customers and contacts are in scope.'),
 ('labeling in multiple languages','Translate labels with language tags while keeping the concept IRI stable. Review equivalence of meaning, regional terminology and fallback display policy.', 'A concept with labels in English and Hindi remains one concept, not two matched concept duplicates.'),
 ('turtle semicolon syntax','The Turtle semicolon continues with the same subject and a new predicate-object pair. It is textual shorthand, not an additional graph relationship.', 'ex:Asha ex:enrolledIn ex:Course ; ex:role "Learner" . creates two triples for ex:Asha.'),
 ('turtle comma syntax','The Turtle comma continues with the same subject and predicate but supplies another object. It expands to separate triples with the same subject and predicate.', 'ex:Course ex:hasLearner ex:Asha, ex:Ravi . yields two ex:hasLearner statements.'),
 ('rdf lists','RDF collections represent ordered lists with rdf:first, rdf:rest and rdf:nil; order is part of the structure. RDF container vocabularies are distinct and should not be conflated with collection semantics.', 'Only use an ordered list when position changes the meaning; most simple multi-valued properties do not need it.'),
 ('json-ld context','A JSON-LD @context maps JSON keys to IRIs and controls how values are interpreted. In particular, @id and @type prevent accidental treatment of resource identifiers as plain strings.', 'Without the intended @context, a consumer may interpret a field as ordinary JSON rather than a link in an RDF graph.'),
 ('named graphs','An RDF dataset can contain a default graph and named graphs. A named graph can delimit snapshots or sources, but the graph name alone does not prove provenance or credibility.', 'A separate named graph for each ingest job supports comparisons; attach source and time metadata deliberately.'),
 ('rdfs:domain inference','rdfs:domain of a property implies a type for every subject using the property; it is not a constraint that rejects unexpected subjects.', 'If ex:hasManager has domain ex:Department, ex:Person ex:hasManager ex:Alex can infer that Person is a Department under RDFS.'),
 ('rdfs:range inference','rdfs:range implies a type for every object of a resource-valued property; datatype ranges participate in RDF semantics as appropriate. Misusing range can introduce unintended types.', 'If ex:manages has range ex:Project then its objects are projects under RDFS entailment.'),
 ('rdfs:subpropertyof','A subproperty assertion entails the corresponding superproperty assertion for the same subject and object. Property hierarchies should express genuine meaning specialization.', 'ex:primarySteward rdfs:subPropertyOf ex:steward implies the more general stewardship relation.'),
 ('equivalent classes','owl:equivalentClass states logical class equivalence in both directions. It is stronger than sharing a similar name or having related labels.', 'Use it only when class definitions are extensionally equivalent under the intended semantics.'),
 ('disjoint classes','owl:disjointWith indicates that two classes cannot share an individual in a consistent interpretation. That can expose modeling contradictions.', 'An individual typed into two disjoint classes yields an inconsistency for suitable reasoners, not an ordinary SHACL error report.'),
 ('functional properties','An OWL functional property has at most one property value per subject in a model; two asserted resources may therefore be inferred equivalent rather than causing immediate validation failure.', 'If duplicate values must be flagged in supplied RDF data, use sh:maxCount 1 in SHACL.'),
 ('inverse properties','owl:inverseOf links two properties so an assertion using one entails the reversed assertion using the other.', 'ex:owns owl:inverseOf ex:ownedBy allows a reasoner to derive ex:Team ex:owns ex:Dataset from ex:Dataset ex:ownedBy ex:Team.'),
 ('transitive properties','A transitive property supports an inferred link from A to C when A→B and B→C hold for that property. Not every hierarchy-like relation is safely transitive.', 'Consider ex:partOf only with explicit modeling assumptions about whether intermediate organization levels compose transitively.'),
 ('symmetric properties','A symmetric object property entails B→A from A→B. This is suitable for some social or spatial relations, but not for ownership or parenthood.', 'Avoid accidentally declaring a directed business control relationship symmetric.'),
 ('property chains','An OWL property-chain axiom derives a property link from an ordered sequence of relations. Chains require supported reasoners/profiles and careful performance evaluation.', 'A chain hasParent ∘ hasSibling is not automatically a safe family inference without a carefully verified domain model.'),
 ('existential restrictions','An existential restriction (someValuesFrom) expresses that members of a class have at least one related value in another class. OWL may satisfy the restriction without an explicitly named source record.', 'Use SHACL minCount when your rule means a data publisher must actually provide a value.'),
 ('universal restrictions','An allValuesFrom restriction says that all values linked by a property belong to the specified class; it does not imply at least one value exists.', 'Combine with a minimum requirement only when the intended logical semantics demands it.'),
 ('qualified cardinality','Qualified cardinality counts property fillers meeting a class expression; it differs from counting all source records in a database.', 'Reasoner cardinality may induce equality between individuals under OWL semantics rather than reporting a missing-data problem.'),
 ('property paths','SPARQL property paths compactly describe walks through specific predicates; they are not a general guarantee of shortest-path behavior or a simple list of materialized intermediate nodes.', 'ex:partOf+ finds one or more transitive steps across partOf edges; include cycle and duplicate-path tests.'),
 ('optional matches','OPTIONAL enriches matching rows with additional bindings without requiring the optional pattern to match. Filters that depend on unbound variables need careful placement.', 'A dataset with no description can still appear when description is OPTIONAL.'),
 ('union patterns','UNION combines solutions from alternative graph patterns. If branches bind different variables, some result cells can be unbound.', 'Retrieve both createdBy and maintainedBy relations only if they represent acceptable answers to the business question.'),
 ('distinct','DISTINCT removes duplicate projected result rows; it cannot repair semantically duplicated source identities.', 'A dataset may appear twice after a join with two owners. Determine whether the query should group the owners instead.'),
 ('group by','GROUP BY aggregates solutions by selected terms; variables in SELECT must follow aggregation/projection requirements.', 'Group datasets by publisher and COUNT distinct dataset IRIs to avoid counting joined descriptive rows twice.'),
 ('having','HAVING filters groups after aggregation, whereas FILTER generally restricts solutions before grouping.', 'To find teams owning more than three datasets, group by team and apply HAVING(COUNT(DISTINCT ?dataset)>3).'),
 ('construct queries','SPARQL CONSTRUCT returns an RDF graph generated from matched bindings. It is useful for controlled graph projections or transformation, not only tabular reports.', 'Carefully govern minted IRIs and filters so projection does not accidentally publish sensitive intermediate nodes.'),
 ('ask queries','SPARQL ASK returns a boolean indicating whether the WHERE pattern has at least one solution, making it useful for bounded acceptance checks.', 'ASK whether any published dataset lacks an owner only when the negative pattern and target dataset scope are modeled correctly.'),
 ('federated service queries','SERVICE delegates part of a SPARQL query to another endpoint; availability, credentials, consistency and join cardinality become distributed concerns.', 'Benchmark partial failures and permission boundaries rather than assuming a federated query is as reliable as local data.'),
 ('minimum counts','sh:minCount requires at least N values for a property path on each focus node. It checks the supplied data graph (under the chosen validation settings).', 'A published dataset missing dct:title fails a shape with sh:minCount 1.'),
 ('maximum counts','sh:maxCount limits the number of values along a property path for the focus node; it is different from an OWL functional-property axiom.', 'When a contract permits exactly one owner, combine minCount 1 and maxCount 1.'),
 ('severity levels','SHACL report severity communicates whether a violation is fatal, a warning or informational according to your policy. Severity alone does not decide CI behavior.', 'Define which severities block a publication, and log waivers with expiry and stewardship approval.'),
 ('validation reports','SHACL validation reports are RDF graphs with focus nodes, source shapes and result details. Parse these report terms to build a reproducible UI.', 'Avoid inferring the business root cause solely from the number of violations; inspect relevant paths and source records.'),
 ('entity resolution','Entity resolution estimates whether source records refer to the same real-world entity. Candidate generation, comparison, scoring and human adjudication are distinct stages.', 'A high text similarity score can coexist with authoritative identifier conflicts; do not automatically merge such pairs.'),
 ('data lineage','Lineage records dependencies and transformations among data assets and processing steps. It differs from business glossary terminology and does not by itself verify quality.', 'If a CRM field changes, trace mapping jobs, governed master entities and consuming dashboards to estimate downstream impact.'),
 ('provenance with prov-o','PROV-O distinguishes entities, activities and agents plus relations such as prov:wasDerivedFrom, prov:wasGeneratedBy and prov:wasAssociatedWith.', 'Record the source extraction, transformation run, and publisher to explain why a given output triple or dataset exists.'),
 ('change data capture','CDC captures source changes for downstream processing. Correctness depends on source ordering, exactly-once expectations, replay, delete handling and idempotent identifiers.', 'An update stream may repeat a message after failure; the graph consumer should produce the same final state on retry.'),
 ('graph storage models','RDF triple stores typically index subject/predicate/object combinations and may use named graphs; property-graph engines store typed edges and properties differently.', 'Choose based on query semantics, interoperability, update patterns and operational requirements—not only benchmark headline numbers.'),
 ('index design','Graph index design depends on dominant query access paths, cardinality distributions and update load. Extra indexes speed some reads but cost space and write work.', 'Measure an actual SPARQL workload and compare plans before altering index configuration.'),
 ('knowledge graph evaluation metrics','Evaluate answer correctness, completeness, entity resolution, relation precision, schema quality, freshness, latency and governance against explicit use cases.', 'A graph with more triples may perform worse if it contains duplicate identities or unsupported source claims.'),
 ('graph unlearning and deletion','Removing a base triple may leave derived inferences, materialized results, caches, embeddings and replicated copies. A deletion plan must account for every derived artifact.', 'Run a dependency-impact check, retract affected assertions and rerun inference/embeddings where necessary; verify deletion evidence.'),
 ('graph data contracts','Graph data contracts specify what producers guarantee about identifiers, vocabularies, shapes, provenance and update behavior. Consumer compatibility must be tested version by version.', 'A change from ex:ownedBy to ex:steward is not just renaming if its meaning, domain or cardinality changes.'),
]

def precise_notes(title):
 t=title.lower().strip(' ?')
 for key,one,two in SPECIFIC:
  if t==key or key in t and len(key)>12:
   return [one,two]
 return []

def best_profile(title,path):
 t=title.lower()
 for p in PROFILES:
  if any(k in t for k in p[1]):return p
 return next(p for p in PROFILES if p[0] in {'Ontology Design','General Data'} and (p[0]=='General Data' if path=='foundations' else True))

def core_key(r):
 if r['id'] in KEY_CORE:return KEY_CORE[r['id']]
 t=r['title'].lower()
 for key,term in [('sparql','sparql'),('shacl','shacl'),('rdf','rdf-triples'),('turtle','turtle'),('skos','skos'),('owl','owl'),('rdfs','rdfs'),('metadata','metadata'),('master','master'),('reference','reference'),('graphrag','graphrag')]:
  if t.strip()==term or (r['id'].startswith('ent-') and t in ['metadata catalog','reference data','master data']):return key
 return None

def lesson(r):
 name=r['title'].rstrip('?').strip(); path=r['path']; scenario,inputs,interface,objective=PATHS[path]
 prof=best_profile(name,path); ptitle,_,definition,example,limit,test,q,ans,wrong=prof
 code,comment=DOMAIN_CODE[path]
 key=core_key(r)
 # Ensure scope is concrete even when a title is very specialized.
 # Each article has topic-specific material *plus* an independently reusable enterprise case.
 summary=f"In this chapter, {name.lower()} is examined as a practical decision in {scenario}. You will identify what the term means, when to apply it, how to represent the decision, and how to check that an implementation behaves as intended."
 explain=[
  f"{definition} The specific question for {name.lower()} is which facts or rules a consumer may rely on and which assumptions must be recorded separately.",
  f"The working context is {scenario}. It contains {inputs}; the intended interface is {interface}. Use this context to distinguish a semantic agreement (meaning) from a data-format agreement (syntax) and a quality agreement (testable expectations).",
  f"{example} For {name.lower()}, explicitly identify the authoritative source, the affected identifiers or terms, the version you would publish, and the consumer that depends on the result. This is more valuable than creating additional classes without a requirement.",
 ]
 worked=[
  f"Start from a business question: how could a user {objective}? Translate it to a small set of named entities, properties, and testable statements. Record the expected answer before writing mappings or queries.",
  f"Now apply {name.lower()}: {example} Mark which part is asserted in the source data, which is a mapping or governance decision, and which result is inferred or validated after loading the graph.",
  f"Consider a counterexample. {limit} Document whether the correct behavior is to reject, quarantine, review or retain the input with an explicit quality warning.",
  f"Finally, check one success path and one failure path: {test} Keep the exact input and output artifacts so a teammate can reproduce the outcome.",
 ]
 decisions=[
  f"Scope: use {name.lower()} only where it supports the question being answered; do not model unrelated fields merely because they are available.",
  f"Identifiers and semantics: decide which source owns the meaning, whether identifiers are stable, and whether the terms describe the same real-world concept across systems.",
  f"Operational boundary: {limit}",
  f"Proof: {test} Log the result and tie it to the current mapping, ontology or reference-data version.",
 ]
 verification=[
  'Positive case: a valid fixture gives the expected answers or validation result, with stable identifiers and correct datatypes.',
  'Negative case: remove a required value, introduce a contradictory mapping, or change a reference code; observe and explain the outcome.',
  'Change case: simulate a new source version or renamed label, then test downstream impact and compatibility.',
  'Evidence: capture the relevant RDF/query/report artifact, source provenance, and a short explanation of why the result is correct.'
 ]
 notes=[
  f"Read the example below as a **pattern**, not a universal implementation of {name.lower()}. It uses invented IRIs and safe synthetic entities; choose real standards and appropriate constraints for your own domain.",
  f"{comment} To extend the pattern, add the source record identifier, the responsible owner, and a test that compares the graph with the intended business answer.",
 ]
 question_mode=sum(ord(c) for c in r['id'])%3
 if question_mode==0:
  checkq=f'For {name.lower()} in {scenario}, which technical principle should guide your design?'
  checka=definition.split('. ')[0].rstrip('.')+'.'
  distractors=['Treat the display label as a globally reliable entity identifier.','Assume exporting RDF proves every business rule has been satisfied.']
 elif question_mode==1:
  checkq=f'Which implementation risk matters when applying {name.lower()} in {scenario}?'
  checka=limit
  distractors=['Once a graph parses, source identifiers and stewardship decisions can be ignored.','All values and classes become correct by increasing the number of relationships.']
 else:
  checkq=f'Which acceptance check would meaningfully verify {name.lower()}?'
  checka=test
  distractors=['Check that the graph looks symmetrical without inspecting RDF content.','Run a successful export without testing valid and invalid source records.']
 text={
  'subtitle':summary,'topicFacts':precise_notes(name),'core':explain,'worked':worked,'decisions':decisions,'verification':verification,
  'exampleCode':code,'exampleNotes':notes,'profile':ptitle,
  'reflection':[f"Explain in your own words how {name.lower()} differs from a generic attribute or tag in this scenario.",f"What new error might appear if a second source disagrees on the identity, code or relationship? Describe how you would detect it.",f"What evidence would persuade a data steward to approve the change for production?"],
  'recap':f"{name}: specify meaning, authority, representation, negative-case behavior, and a repeatable test. The practical goal is to {objective}, not simply to grow the graph.",
  'review':{'q':checkq,'a':checka,'wrong':distractors},'reference':r['source_url'],
  'readingMinutes':5,'practiceMinutes':14 if path not in ['foundations','modeling'] else 10,
 }
 if key and key in CORE:
  why,nuance,do,trade=CORE[key]
  text['spotlight']=[why,nuance,do,trade]
  text['readingMinutes']=7
 return text

out={r['id']:lesson(r) for r in rows}
assert len(out)==613 and len(set(out))==613
outpath=ROOT/'assets/learning-guides.js'
outpath.write_text('/* Tāttvikī v10 original structured study guides for all 613 indexed topics. */\nwindow.TATTVIKI_GUIDES='+json.dumps(out,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
print('Generated',len(out),'expanded reading pages',outpath.stat().st_size,'bytes')
